struct Counter { n: i32 }
impl Counter {
    fn new() -> Counter { Counter { n: 0 } }
    fn bump(&mut self) -> i32 {
        self.n += 1;
        self.n
    }
}
fn main() {
    let mut c = Counter::new();
    println!("{} {}", c.bump(), c.bump());
}

